<?php $editing=isset($record); $row=$record ?? []; ?><form class="stack" action="/career/<?= e($formType) ?><?= $editing ? '/'.e($row['id']).'/edit' : '' ?>" method="post"><?= csrf_field() ?>
<?php if ($formType==='applications'): ?>
<label><?= e(t('Organization')) ?><input name="organization" value="<?= e($row['organization'] ?? '') ?>" maxlength="200" required></label><label><?= e(t('Role')) ?><input name="role" value="<?= e($row['role'] ?? '') ?>" maxlength="200" required></label><label><?= e(t('Application link or reference')) ?><input name="resource" value="<?= e($row['resource'] ?? '') ?>" maxlength="1000"></label><label><?= e(t('Status')) ?><select name="status"><?php foreach (CareerService::APPLICATION_STATUSES as $key=>$label): ?><option value="<?= e($key) ?>" <?= ($row['status'] ?? 'saved')===$key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label><?= e(t('Applied date')) ?><input type="date" name="applied_date" value="<?= e($row['applied_date'] ?? '') ?>"></label><label><?= e(t('Application deadline')) ?><input type="date" name="deadline" value="<?= e($row['deadline'] ?? '') ?>"></label><label><?= e(t('Next interview')) ?><input type="datetime-local" name="interview_at" value="<?= e(str_replace(' ','T',$row['interview_at'] ?? '')) ?>"></label>
<?php else: ?>
<label><?= $formType==='skills' ? t('Skill') : t('Course') ?> <?= e(t('name')) ?><input name="name" value="<?= e($row['name'] ?? '') ?>" maxlength="<?= $formType==='skills' ? 150 : 200 ?>" required></label>
<?php if ($formType==='courses'): ?><label><?= e(t('Provider')) ?><input name="provider" value="<?= e($row['provider'] ?? '') ?>" maxlength="200"></label><label><?= e(t('Course link or reference')) ?><input name="resource" value="<?= e($row['resource'] ?? '') ?>" maxlength="1000"></label><label><?= e(t('Related skill')) ?><select name="skill_id"><option value=""><?= e(t('No linked skill')) ?></option><?php foreach ($skills as $skill): ?><option value="<?= e($skill['id']) ?>" <?= ($row['skill_id'] ?? null)===$skill['id'] ? 'selected' : '' ?>><?= e($skill['name']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Status')) ?><select name="status"><?php foreach (CareerService::COURSE_STATUSES as $key=>$label): ?><option value="<?= e($key) ?>" <?= ($row['status'] ?? 'planned')===$key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><?php endif; ?>
<label><?= $formType==='skills' ? t('Self-assessed progress') : t('Course completion') ?> %<input name="progress" type="number" min="0" max="100" value="<?= e($row['progress'] ?? 0) ?>" required></label><label><?= e(t('Target date')) ?><input type="date" name="<?= $formType==='skills' ? 'target_date' : 'due_date' ?>" value="<?= e($formType==='skills' ? ($row['target_date'] ?? '') : ($row['due_date'] ?? '')) ?>"></label>
<?php endif; ?>
<label><?= e(t('Notes')) ?><textarea name="notes" maxlength="<?= $formType==='applications' ? 5000 : 3000 ?>" rows="3"><?= e($row['notes'] ?? '') ?></textarea></label><button><?= $editing ? t('Save changes') : t('Add ').e(match($formType) {'skills'=>'skill','courses'=>'course',default=>'application'}) ?></button></form>
